// Erzeugt von medikamente/scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"abacavir-lamivudin-dolutegravir":{"wirkmechanismus":"Hemmt die Vermehrung von HIV an zwei Stellen. Dolutegravir blockiert die Integrase und verhindert den Einbau der Virus-DNA in das Erbgut der Wirtszelle (Strangtransfer). Abacavir (ein Guanosin-Analogon, aktiv als Carbovir-Triphosphat) und Lamivudin (ein Cytidin-Analogon) werden in den Zellen phosphoryliert, von der Reversen Transkriptase in die Virus-DNA eingebaut und führen zum Kettenabbruch. Die Kombination mehrerer Wirkprinzipien beugt Resistenzen vor.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit","Durchfall"],"haeufig":["Überempfindlichkeitsreaktion auf Abacavir (Fieber, Ausschlag, Übelkeit, Bauchschmerzen, Atembeschwerden, Müdigkeit) – lebensbedrohlich möglich","Schlaflosigkeit, abnorme Träume, Albträume, Depression, Angst","Schwindel, Schläfrigkeit, Lethargie","Erbrechen, Blähungen, Bauchschmerzen, Sodbrennen","Hautausschlag, Juckreiz, Haarausfall","Gelenk- und Muskelbeschwerden","Müdigkeit, Schwäche, Fieber, Appetitlosigkeit","Erhöhte Leberwerte und Kreatinkinase (CK), Gewichtszunahme"],"gelegentlich":["Hepatitis (Leberentzündung)","Suizidgedanken oder Suizidversuch, Panikattacken (vor allem bei psychischer Vorerkrankung)","Neutropenie, Anämie, Thrombozytopenie","Erhöhte Triglyceride, erhöhter Blutzucker","Immunrekonstitutionssyndrom"],"selten":["Pankreatitis (Bauchspeicheldrüsenentzündung)","Akutes Leberversagen","Rhabdomyolyse (Muskelzerfall)","Angioödem (Schwellung von Haut und Schleimhäuten)","Laktatazidose (Übersäuerung des Blutes)","Suizid (bei psychischer Vorerkrankung)"],"sehrSelten":["Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Erythroblastopenie (Aplasie der roten Blutzellen)","Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit angewendet werden. Ein früher vermutetes erhöhtes Risiko für Neuralrohrdefekte durch Dolutegravir zum Zeitpunkt der Empfängnis hat sich in grösseren Untersuchungen nicht klar bestätigt – Schwangerschaft mit der HIV-Fachperson planen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Vor Beginn HLA-B*5701-Test; die Warnkarte zur Abacavir-Überempfindlichkeit immer bei sich tragen.","Bei Fieber, Ausschlag, Übelkeit, Atembeschwerden oder starker Müdigkeit sofort ärztlich melden; nach einer Überempfindlichkeitsreaktion nie wieder einnehmen.","Antazida, Mineralstoff- und Eisenpräparate zeitversetzt einnehmen (Triumeq 2 Stunden davor oder 6 Stunden danach).","Einmal täglich mit oder ohne Mahlzeit einnehmen; bei Hepatitis B nicht eigenmächtig absetzen."],"darreichung":["Filmtabletten"]},"acenocoumarol":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es die Wirkung von Vitamin K in der Leber blockiert. Acenocoumarol hemmt die Vitamin-K-Epoxid-Reduktase (VKORC1); dadurch werden die Gerinnungsfaktoren II, VII, IX und X sowie Protein C und S nicht mehr funktionsfähig gebildet. Die volle Wirkung setzt nach 2–3 Tagen ein, zu Beginn wird oft überlappend Heparin gegeben. Mit einer Halbwertszeit von etwa 8–11 Stunden wirkt es deutlich kürzer als Phenprocoumon, der INR normalisiert sich nach dem Absetzen innert weniger Tage; abgebaut wird es vor allem über CYP2C9, Gegenmittel ist Vitamin K.","nebenwirkungen":{"haeufig":["Blutungen unterschiedlicher Schwere – meist leicht (Zahnfleisch- und Nasenbluten, Blutergüsse, Blut im Urin), seltener schwer (Magen-Darm-Blutung, Hirnblutung)"],"selten":["Appetitlosigkeit, Übelkeit, Erbrechen","Allergische Hautreaktionen (Nesselsucht, Ausschlag, Juckreiz)","Haarausfall"],"sehrSelten":["Hämorrhagische Hautnekrosen (Cumarin-Nekrose), meist bei angeborenem Protein-C-Mangel","Gefässentzündung (Vaskulitis)","Leberschäden"],"unbekannt":["Calciphylaxie (schmerzhafte Hautgeschwüre durch Gefässverkalkung), vor allem bei Nierenkrankheit"]},"schwangerschaft":"Kontraindiziert: Acenocoumarol kann das Kind schädigen (Cumarin-Embryopathie, Blutungen). Frauen im gebärfähigen Alter müssen sicher verhüten; bei Kinderwunsch oder Schwangerschaft umgehend ärztlich auf Heparin umstellen.","stillzeit":"Geht nur in geringen Mengen in die Muttermilch über; Stillen ist nach ärztlicher Abwägung möglich, das Kind erhält vorsorglich Vitamin K.","hinweise":["Regelmässige INR-Kontrollen einhalten; Antikoagulationsausweis mitführen und alle Ärztinnen, Ärzte, Zahnärzte und Apotheken informieren.","Keine neuen Medikamente, auch keine rezeptfreien Schmerzmittel oder pflanzlichen Mittel (z. B. Johanniskraut), ohne Rücksprache – viele verändern den INR.","Ernährung gleichmässig halten: die Menge Vitamin-K-reicher Lebensmittel (Kohl, Spinat, Sauerkraut, grünes Blattgemüse) nicht plötzlich stark ändern; Alkohol nur in kleinen Mengen.","Täglich zur gleichen Zeit einnehmen; bei Zeichen einer Blutung (schwarzer Stuhl, Blut im Urin, starke Kopfschmerzen) sofort ärztliche Hilfe holen."],"darreichung":["Tabletten"]},"acetylsalicylsaeure":{"wirkmechanismus":"Hemmt die Bildung von Botenstoffen, die Schmerz, Fieber und Entzündung auslösen. Acetylsalicylsäure acetyliert die Cyclooxygenasen COX-1 und COX-2 irreversibel und blockiert so die Prostaglandinsynthese. In niedriger Dosis (75–100 mg pro Tag) steht die Hemmung der Thromboxan-A2-Bildung in den Blutplättchen im Vordergrund: Weil Thrombozyten keinen Zellkern haben und das Enzym nicht nachbilden können, hält die Hemmung ihre ganze Lebensdauer von 7–10 Tagen an.","nebenwirkungen":{"haeufig":["Magen-Darm-Beschwerden wie Sodbrennen, Übelkeit, Bauchschmerzen","Dyspepsie (Verdauungsbeschwerden)","Geringe Blutverluste aus dem Magen-Darm-Trakt (Mikroblutungen)"],"gelegentlich":["Überempfindlichkeitsreaktionen der Haut (Ausschlag, Juckreiz, Nesselsucht)","Magen-Darm-Blutungen","Nasenbluten, Zahnfleischbluten"],"selten":["Magen-Darm-Geschwüre, Durchbruch (Perforation)","Bronchospasmus (Verkrampfung der Atemwege) bei Analgetika-Asthma","Schwere Blutungen, z. B. Hirnblutung","Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen"],"sehrSelten":["Erhöhte Leberwerte","Nierenfunktionsstörungen","Hypoglykämie (Unterzuckerung)","Reye-Syndrom bei Kindern"],"unbekannt":["Schwindel und Ohrensausen (Tinnitus) als Zeichen einer Überdosierung","Eisenmangelanämie durch verborgene Blutungen","Hämolyse (Blutzerfall) bei G6PD-Mangel"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach ärztlicher Abwägung und so kurz und niedrig dosiert wie möglich. Im letzten Drittel in Dosen über 100 mg pro Tag kontraindiziert; niedrig dosierte ASS (z. B. zur Vorbeugung einer Präeklampsie) nur auf ärztliche Verordnung.","stillzeit":"Gelegentliche Einnahme niedriger Dosen ist vertretbar. Bei regelmässiger Einnahme höherer Dosen soll abgestillt werden.","hinweise":["Vor Operationen und Zahnbehandlungen die Einnahme angeben: die Blutungsneigung hält 7–10 Tage an.","Nach dem Essen mit reichlich Flüssigkeit einnehmen; Alkohol erhöht das Risiko für Magenblutungen.","Niedrig dosierte ASS zur Herzinfarkt- oder Schlaganfallvorbeugung nicht eigenmächtig absetzen.","Kindern und Jugendlichen mit Fieber nur auf ärztlichen Rat geben (Reye-Syndrom)."],"darreichung":["Tabletten","Brausetabletten","Magensaftresistente Tabletten","Granulat (Beutel)","Injektionslösung"]},"aciclovir":{"wirkmechanismus":"Hemmt die Vermehrung von Herpesviren in befallenen Zellen. Aciclovir wird bevorzugt in virusinfizierten Zellen durch die virale Thymidinkinase und danach durch zelluläre Enzyme zu Aciclovirtriphosphat umgewandelt. Dieses hemmt die virale DNA-Polymerase und führt nach Einbau in die Virus-DNA zum Kettenabbruch. Gesunde Zellen bleiben weitgehend verschont; ruhende (latente) Viren werden nicht beseitigt, Rückfälle bleiben daher möglich.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel (Tabletten/Infusion)","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen (Tabletten/Infusion)","Juckreiz, Hautausschlag, Lichtempfindlichkeit (Tabletten/Infusion)","Müdigkeit, Fieber (Tabletten/Infusion)","Venenentzündung an der Infusionsstelle, Anstieg von Leber- und Nierenwerten (Infusion)"],"gelegentlich":["Brennen, Stechen, Trockenheit oder Schuppung der Haut (Crème)","Nesselsucht, beschleunigter diffuser Haarausfall (Tabletten/Infusion)"],"selten":["Anaphylaxie (schwere allergische Reaktion), Angioödem","Atemnot","Erhöhte Leber- und Nierenwerte (Tabletten)","Hautrötung, Kontaktdermatitis (Crème)"],"sehrSelten":["Anämie, Leukopenie, Thrombozytopenie","Verwirrtheit, Halluzinationen, Unruhe, Zittern, Ataxie, Sprechstörungen, Krampfanfälle, Schläfrigkeit, Enzephalopathie, Koma – meist bei eingeschränkter Nierenfunktion","Hepatitis, Gelbsucht","Akutes Nierenversagen, Nierenschmerzen"]},"schwangerschaft":"Grosse Schwangerschaftsregister zeigen kein erhöhtes Fehlbildungsrisiko. Tabletten oder Infusion nach ärztlicher Abwägung; die Crème kann angewendet werden.","stillzeit":"Geht in die Muttermilch über; die Mengen gelten als unbedenklich, Stillen ist in der Regel möglich. Crème nicht an der Brust auftragen.","hinweise":["Behandlung so früh wie möglich beginnen – bei Lippenherpes bei den ersten Anzeichen (Kribbeln, Spannungsgefühl).","Während der Behandlung mit Tabletten oder Infusion ausreichend trinken.","Crème mit sauberen Fingern oder Wattestäbchen auftragen, danach Hände waschen; Bläschen nicht aufstechen.","Herpes ist ansteckend: Küssen und Oralverkehr bei Lippenherpes vermeiden, bei Genitalherpes Kondome verwenden."],"darreichung":["Tabletten","Suspension zum Einnehmen","Crème","Infusionslösung (Spital)"]},"adapalen":{"wirkmechanismus":"Normalisiert die Verhornung in den Haarfollikeln, sodass sich weniger Mitesser bilden und bestehende sich lösen. Adapalen ist ein Retinoid der dritten Generation (Naphthoesäure-Abkömmling), das gezielt an die Retinsäure-Rezeptoren RAR-beta und RAR-gamma der Haut bindet und die Ausreifung der Follikelzellen reguliert. Zusätzlich hemmt es Entzündungsvorgänge in der Haut. Die Aufnahme in den Körper ist sehr gering.","nebenwirkungen":{"haeufig":["Trockene Haut","Hautreizung, Rötung (Erythem)","Brennen oder Stechen der Haut","Schuppung (Hautabschälung)"],"gelegentlich":["Juckreiz","Kontaktdermatitis","Sonnenbrand","Vorübergehende Verschlechterung der Akne"],"unbekannt":["Allergische Kontaktdermatitis, Schwellung von Gesicht oder Augenlidern, Angioödem","Hellere oder dunklere Hautverfärbung","Schmerzen der Haut","Verbrennungen an der Auftragsstelle"]},"schwangerschaft":"Kontraindiziert. Auch wenn nur wenig Wirkstoff in den Körper gelangt, gelten Retinoide als potenziell fruchtschädigend; bei Eintritt einer Schwangerschaft die Behandlung beenden.","stillzeit":"Nach Abwägung möglich, da kaum Wirkstoff ins Blut gelangt; nicht auf die Brust auftragen.","hinweise":["Einmal täglich abends dünn auf die gereinigte, trockene Haut auftragen.","Die Wirkung zeigt sich nach 4–8 Wochen; anfangs kann sich die Akne vorübergehend verschlechtern.","Sonnenschutz verwenden und Solarium meiden.","Epiduo enthält Benzoylperoxid und kann Haare und Textilien bleichen."],"darreichung":["Gel","Creme"]},"adenosin":{"wirkmechanismus":"Unterbricht für wenige Sekunden die elektrische Überleitung im Herzen und beendet so kreisende Erregungen, die Herzrasen verursachen. Adenosin aktiviert A1-Rezeptoren im AV-Knoten und Sinusknoten; dadurch öffnen sich Kaliumkanäle, die Zellen werden hyperpolarisiert und die AV-Überleitung wird kurzzeitig blockiert. Über A2-Rezeptoren erweitert es zudem Blutgefässe. Adenosin wird im Blut innerhalb von weniger als 10 Sekunden abgebaut, weshalb es als schneller Bolus gespritzt wird und die Wirkung nur kurz anhält.","nebenwirkungen":{"sehrHaeufig":["Hautrötung (Flush)","Bradykardie, kurze Herzpausen (Asystolie), AV-Block, Extraschläge aus Vorhöfen oder Kammern","Atemnot","Druck- oder Schmerzgefühl in der Brust"],"haeufig":["Kopfschmerzen","Schwindel, Benommenheit","Übelkeit","Angstgefühl","Brennendes Gefühl"],"gelegentlich":["Verschwommenes Sehen","Herzklopfen","Schwitzen","Metallischer Geschmack","Hyperventilation","Druckgefühl im Kopf"],"sehrSelten":["Schwere Bradykardie","Vorhofflimmern, Kammerflimmern, Torsade de pointes","Bronchospasmus","Reaktionen an der Injektionsstelle"],"unbekannt":["Herzstillstand, teils tödlich","Herzinfarkt","Atemstillstand","Krampfanfälle","Bewusstlosigkeit, Ohnmacht (Synkope)","Blutdruckabfall","Erbrechen","Anaphylaktische Reaktion, Angioödem"]},"schwangerschaft":"Nur wenige Daten; nur anwenden, wenn der Nutzen das mögliche Risiko klar überwiegt.","stillzeit":"Keine Daten; wegen der sehr kurzen Wirkdauer ist ein Risiko für den Säugling unwahrscheinlich – Anwendung nach ärztlicher Abwägung.","hinweise":["Wird nur unter EKG-Überwachung mit bereitstehender Notfallausrüstung gegeben.","Ein kurzes Engegefühl in der Brust, Atemnot und Hitzegefühl sind häufig und verschwinden meist innerhalb einer Minute.","Kaffee, Tee, Cola und Energydrinks können die Wirkung abschwächen."],"darreichung":["Injektionslösung"]},"adrenalin":{"wirkmechanismus":"Hebt den Blutdruck, öffnet die Atemwege und bremst die allergische Reaktion innert Minuten. Adrenalin stimuliert Alpha-Rezeptoren (Gefässverengung, Abschwellen von Schleimhaut-Ödemen) sowie Beta-1-Rezeptoren (stärkere und schnellere Herzschläge) und Beta-2-Rezeptoren (Erweiterung der Bronchien). Zudem hemmt es die Freisetzung von Histamin und anderen Entzündungsstoffen aus Mastzellen. Die Wirkung tritt nach Injektion in den Oberschenkelmuskel rasch ein, hält aber nur kurz an.","nebenwirkungen":{"selten":["Stress-Kardiomyopathie (Takotsubo-Syndrom)"],"unbekannt":["Herzklopfen, Herzrasen (Tachykardie)","Herzrhythmusstörungen bis Kammerflimmern","Angina pectoris (Brustenge), Myokardischämie","Blutdruckanstieg, Gefässverengung, Blässe","Angst, Unruhe, Zittern, Kopfschmerzen, Schwindel, Halluzinationen","Schwitzen, Übelkeit, Erbrechen, Schwäche","Hyperglykämie (erhöhter Blutzucker), Hypokaliämie (Kaliummangel), metabolische Azidose","Bronchospasmus","Verletzung oder Infektion an der Injektionsstelle; Durchblutungsstörung bei versehentlicher Injektion in Finger, Hände oder Füsse"]},"schwangerschaft":"Bei Anaphylaxie oder Wiederbelebung lebensrettend und deshalb auch in der Schwangerschaft anzuwenden; Adrenalin kann die Durchblutung der Plazenta vorübergehend vermindern.","stillzeit":"Adrenalin wird über den Darm des Säuglings kaum aufgenommen; die Notfallanwendung ist in der Stillzeit erlaubt.","hinweise":["Im Notfall nicht zögern: Pen in die Aussenseite des Oberschenkels drücken, auch durch die Kleidung; danach Notruf 144 wählen und liegen bleiben (bei Atemnot sitzen).","Immer zwei Adrenalin-Pens dabeihaben; tritt nach 5–15 Minuten keine Besserung ein, den zweiten Pen anwenden.","Nie in Finger, Hände, Füsse oder ein Blutgefäss injizieren.","Verfalldatum regelmässig prüfen, Pen vor Hitze und Kälte schützen; verfärbte oder trübe Lösung nicht verwenden."],"darreichung":["Fertigpen (Autoinjektor)","Injektionslösung","Fertigspritze"]},"aktivkohle":{"wirkmechanismus":"Bindet viele Giftstoffe an seiner Oberfläche, sodass sie mit dem Stuhl ausgeschieden statt ins Blut aufgenommen werden. Aktivkohle ist eine hochporöse Kohle mit einer inneren Oberfläche von rund 1000 Quadratmetern pro Gramm, an die sich Medikamente und Gifte physikalisch anlagern (Adsorption). Wiederholte Gaben unterbrechen zudem den Kreislauf von Stoffen, die über Galle oder Darmwand erneut in den Darm gelangen. Aktivkohle selbst wird nicht aufgenommen. Schlecht oder gar nicht gebunden werden Alkohole, Säuren und Laugen, Eisen, Lithium und andere Metallsalze, Cyanid sowie Erdöldestillate.","nebenwirkungen":{"sehrHaeufig":["Schwarzfärbung des Stuhls (harmlos)"],"haeufig":["Erbrechen","Verstopfung (Obstipation)"],"unbekannt":["Durchfall (v. a. zusammen mit Abführmitteln)","Aspiration (Einatmen) von Kohle mit Lungenentzündung","Darmverschluss durch Kohleansammlungen bei wiederholter Gabe"]},"schwangerschaft":"Aktivkohle wird nicht aufgenommen; bei Vergiftungen in der Schwangerschaft anwendbar.","stillzeit":"Anwendung in der Stillzeit möglich.","hinweise":["Bei Vergiftungsverdacht sofort Tox Info Suisse (Notruf 145) oder den Notruf 144 kontaktieren; Kohle wirkt am besten innerhalb der ersten Stunde nach der Giftaufnahme.","Der Stuhl färbt sich schwarz – das ist harmlos.","Andere Medikamente mindestens 2 Stunden vor oder nach der Kohle einnehmen."],"darreichung":["Granulat zur Herstellung einer Suspension zum Einnehmen","Kapseln (Kombination mit Hefe)"]},"albumin-human":{"wirkmechanismus":"Hält Flüssigkeit in den Blutgefässen und stabilisiert so den Kreislauf. Albumin macht über die Hälfte der Eiweisse im Blutplasma aus und bestimmt rund 80 % des kolloidosmotischen (onkotischen) Drucks, der Wasser in den Gefässen bindet. Eine 4–5 %-Lösung entspricht dem Plasma, 20–25 %-Lösungen ziehen zusätzlich Wasser aus dem Gewebe in die Gefässe (rund 18 ml Wasser pro Gramm Albumin). Albumin dient im Blut zudem als Transporteiweiss für Hormone, Bilirubin und viele Arzneimittel.","nebenwirkungen":{"selten":["Flush (Hitzegefühl, Hautrötung)","Nesselsucht","Fieber","Übelkeit"],"sehrSelten":["Anaphylaktischer Schock (schwere allergische Reaktion)"],"unbekannt":["Kreislaufüberlastung mit Lungenödem bei zu rascher oder zu grosser Infusionsmenge"]},"schwangerschaft":"Albumin ist ein normaler Bestandteil des menschlichen Blutes; schädliche Wirkungen sind nicht zu erwarten. Anwendung bei klarer Indikation möglich.","stillzeit":"Anwendung möglich; schädliche Wirkungen auf den Säugling sind nicht zu erwarten.","hinweise":["Wird nur im Spital unter Überwachung von Blutdruck, Puls und Flüssigkeitshaushalt gegeben.","20–25 %-Lösungen nicht mit Wasser für Injektionszwecke verdünnen – Gefahr der Hämolyse (Auflösung roter Blutkörperchen).","Nicht mit anderen Arzneimitteln, Vollblut oder Erythrozytenkonzentraten mischen.","Bei jeder Gabe werden Produktname und Chargennummer dokumentiert."],"darreichung":["Infusionslösung 4–5 % (isoonkotisch)","Infusionslösung 20–25 % (hyperonkotisch)"]},"alfuzosin":{"wirkmechanismus":"Erleichtert das Wasserlösen, indem es die Muskulatur in Prostata, Blasenhals und Harnröhre entspannt. Alfuzosin blockiert Alpha-1-Adrenozeptoren, die im unteren Harntrakt die Spannung der glatten Muskulatur steuern; dadurch sinkt der Widerstand beim Harnabfluss, der Harnstrahl wird kräftiger und Restharn sowie Reizbeschwerden nehmen ab. Die Prostata selbst wird dabei nicht kleiner. Weil auch Alpha-1-Rezeptoren in den Blutgefässen gehemmt werden, kann der Blutdruck sinken, besonders beim Aufstehen und zu Behandlungsbeginn.","nebenwirkungen":{"haeufig":["Schwindel, Benommenheit, Drehschwindel","Kopfschmerzen","Übelkeit, Bauchschmerzen","Asthenie (Schwäche), Unwohlsein"],"gelegentlich":["Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), v. a. zu Behandlungsbeginn","Synkope (Ohnmacht)","Herzklopfen, beschleunigter Puls","Schläfrigkeit, Sehstörungen","Schnupfen (Rhinitis)","Durchfall, Mundtrockenheit","Hautausschlag, Juckreiz","Ödeme (Wassereinlagerungen), Hitzewallungen, Brustschmerzen"],"sehrSelten":["Neu auftretende oder verstärkte Angina pectoris bei bestehender koronarer Herzkrankheit","Nesselsucht, Angioödem"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Kataraktoperation","Priapismus (schmerzhafte Dauererektion)","Leberschäden, Gelbsucht","Vorhofflimmern","Neutropenie, Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Erbrechen"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Retardtablette jeden Tag direkt nach derselben Mahlzeit (meist dem Abendessen) unzerkaut ganz schlucken.","Vor allem zu Beginn kann Schwindel auftreten: langsam aufstehen, sich bei Schwindel hinlegen und vorsichtig sein beim Autofahren.","Vor einer Augenoperation am grauen Star oder einer Narkose die Einnahme angeben."],"darreichung":["Retardtabletten"]},"alirocumab":{"wirkmechanismus":"Senkt das LDL-Cholesterin stark, indem es dafür sorgt, dass die Leber mehr «Cholesterin-Fänger» behält. Alirocumab ist ein humaner monoklonaler IgG1-Antikörper, der das im Blut zirkulierende Protein PCSK9 (Proproteinkonvertase Subtilisin/Kexin Typ 9) bindet. PCSK9 bewirkt normalerweise, dass LDL-Rezeptoren in der Leberzelle abgebaut werden; ist es blockiert, stehen mehr Rezeptoren an der Zelloberfläche zur Verfügung und entfernen LDL-Cholesterin aus dem Blut. Als Eiweiss wird Alirocumab wie körpereigene Antikörper abgebaut, nicht über Leberenzyme.","nebenwirkungen":{"haeufig":["Beschwerden der oberen Atemwege (Halsschmerzen, Schnupfen, Niesen)","Juckreiz","Reaktionen an der Injektionsstelle (Rötung, Juckreiz, Schwellung, Schmerzen)"],"selten":["Überempfindlichkeitsreaktionen, Überempfindlichkeitsvaskulitis (allergische Gefässentzündung)","Nesselsucht, nummuläres Ekzem (münzförmiger Hautausschlag)"],"unbekannt":["Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)","Grippeähnliche Beschwerden"]},"schwangerschaft":"Nicht empfohlen, ausser der Zustand der Frau erfordert eine Behandlung – keine ausreichenden Erfahrungen; Antikörper gelangen vor allem im letzten Drittel zum Ungeborenen.","stillzeit":"Ein Risiko für den gestillten Säugling ist nicht auszuschliessen – ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Im Kühlschrank (2–8 °C) lagern, nicht einfrieren; vor dem Spritzen 30–40 Minuten Raumtemperatur annehmen lassen. Ausserhalb des Kühlschranks (bis 25 °C) höchstens 30 Tage haltbar.","Unter die Haut von Bauch, Oberschenkel oder Oberarm spritzen und die Stelle wechseln.","Keine bekannten Wechselwirkungen mit anderen Medikamenten; Statin und Ernährungsmassnahmen weiterführen."],"darreichung":["Injektionslösung im Fertigpen"]},"alteplase":{"wirkmechanismus":"Löst frische Blutgerinnsel auf und kann so verschlossene Gefässe wieder eröffnen. Alteplase ist ein gentechnisch hergestellter menschlicher Gewebeplasminogenaktivator (rt-PA). Er bindet an das Fibrin im Gerinnsel und wandelt dort Plasminogen in das eiweissspaltende Enzym Plasmin um, das das Fibrinnetz abbaut. Weil die Aktivierung an Fibrin gebunden viel stärker ist, wirkt Alteplase relativ gerinnselspezifisch; dennoch wird auch Fibrinogen im Blut abgebaut, was das Blutungsrisiko erklärt. Die Halbwertszeit beträgt nur wenige Minuten, darum wird es als Bolus mit anschliessender Infusion gegeben.","nebenwirkungen":{"sehrHaeufig":["Blutungen aus verletzten Gefässen und an Einstichstellen, Blutergüsse","Hirnblutung bei der Behandlung des Schlaganfalls","Beim Herzinfarkt: erneute Durchblutungsstörung oder Brustenge, tiefer Blutdruck, Herzschwäche mit Lungenödem, Rhythmusstörungen bei Wiedereröffnung des Gefässes"],"haeufig":["Blutungen im Magen-Darm-Trakt, aus Zahnfleisch, Rachen, Harn- und Geschlechtsorganen","Hirnblutung bei der Behandlung der Lungenembolie","Beim Herzinfarkt: Herzstillstand, kardiogener Schock, erneuter Infarkt"],"gelegentlich":["Hirnblutung bei der Behandlung des Herzinfarkts","Blutungen aus dem Ohr","Beim Herzinfarkt: Embolien, Herzklappenundichtigkeit, Herzbeuteltamponade"],"selten":["Überempfindlichkeitsreaktionen (Ausschlag, Nesselsucht, Bronchospasmus, Angioödem, Blutdruckabfall, Schock)","Augenblutungen","Blutungen in Herzbeutel, Leber oder Lunge","Cholesterinembolien"],"sehrSelten":["Schwere Anaphylaxie","Neurologische Störungen wie Krampfanfälle, Sprachstörungen, Verwirrtheit, Unruhe, Depression oder Psychose (meist im Zusammenhang mit Hirnblutung oder Durchblutungsstörung des Gehirns)"],"unbekannt":["Übelkeit, Erbrechen","Blutungen, die eine Bluttransfusion erfordern"]},"schwangerschaft":"Nur begrenzte Erfahrungen; bei lebensbedrohlicher Erkrankung nach Abwägung von Nutzen und Blutungsrisiko (auch für die Plazenta) anwenden.","stillzeit":"Unbekannt, ob Alteplase in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital durch erfahrenes Personal gegeben; beim Hirnschlag zählt jede Minute – sofort Notruf 144.","Blutdruck und Neurologie werden während und nach der Infusion engmaschig überwacht.","Bei Einnahme von ACE-Hemmern auf Schwellung von Zunge, Lippen und Rachen achten.","Dem Behandlungsteam alle Blutverdünner melden, besonders Marcoumar, Sintrom, Xarelto, Eliquis, Lixiana oder Pradaxa und den Zeitpunkt der letzten Einnahme."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektions- und Infusionslösung"]},"aluminiumhydroxid-magnesiumhydroxid":{"wirkmechanismus":"Bindet überschüssige Magensäure und lindert Sodbrennen rasch. Aluminiumhydroxid und Magnesiumhydroxid reagieren mit der Salzsäure im Magen zu Salzen und Wasser und heben den pH-Wert des Mageninhalts an; dadurch wird auch das Verdauungsenzym Pepsin weniger aktiv. Aluminiumhydroxid wirkt eher verstopfend, Magnesiumhydroxid eher abführend – die Kombination gleicht diese Wirkungen teilweise aus. Aluminium bindet zudem Phosphat im Darm; nur geringe Mengen Aluminium und Magnesium werden ins Blut aufgenommen und über die Nieren ausgeschieden.","nebenwirkungen":{"gelegentlich":["Durchfall","Verstopfung"],"unbekannt":["Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht, Angioödem, Anaphylaxie)","Bauchschmerzen","Hypermagnesiämie (erhöhtes Magnesium im Blut), v. a. bei Niereninsuffizienz","Aluminium-Anreicherung bei Niereninsuffizienz mit Knochenerweichung (Osteomalazie) und Hirnschädigung (Enzephalopathie)","Phosphatmangel (Hypophosphatämie) bei langer, hochdosierter Einnahme"]},"schwangerschaft":"Kurzfristige Einnahme in üblicher Dosierung ist möglich; längere oder hochdosierte Einnahme vermeiden (Aluminiumbelastung des Kindes).","stillzeit":"In üblicher Dosierung möglich; nur geringe Mengen Aluminium und Magnesium gelangen in die Muttermilch.","hinweise":["Bei Bedarf etwa 1 Stunde nach den Mahlzeiten und vor dem Schlafengehen einnehmen; Suspension vor Gebrauch schütteln, Kautabletten gut kauen.","Zu anderen Arzneimitteln 2 Stunden Abstand halten, zu Chinolon-Antibiotika mindestens 4 Stunden.","Ohne ärztlichen Rat nicht länger als 2 Wochen einnehmen."],"darreichung":["Suspension (Gel) zum Einnehmen","Kautabletten"]},"amiodaron":{"wirkmechanismus":"Stabilisiert den Herzrhythmus, indem es die elektrische Erholungsphase der Herzmuskelzellen verlängert. Amiodaron blockiert vor allem Kaliumkanäle und verlängert so Aktionspotenzial und Refraktärzeit in Vorhöfen, AV-Knoten und Kammern (Klasse III). Zusätzlich hemmt es Natrium- und Calciumkanäle sowie Alpha- und Beta-Rezeptoren, was den Puls verlangsamt und die AV-Überleitung bremst. Amiodaron enthält viel Jod, reichert sich im Gewebe an und hat eine sehr lange Halbwertszeit von etwa 50 Tagen; die Wirkung hält nach dem Absetzen noch Wochen bis Monate an.","nebenwirkungen":{"sehrHaeufig":["Hornhautablagerungen im Auge (meist ohne Beschwerden, evtl. farbige Ringe um Lichtquellen)","Übelkeit, Erbrechen, Geschmacksstörungen (v. a. zu Beginn)","Lichtempfindlichkeit der Haut (Photosensibilisierung)","Erhöhte Leberwerte ohne Beschwerden"],"haeufig":["Schilddrüsenunterfunktion oder -überfunktion","Zittern, Albträume, Schlafstörungen","Mässige Bradykardie (verlangsamter Herzschlag)","Lungenschädigung (interstitielle Pneumonitis, Lungenfibrose)","Akute Leberschädigung mit Gelbsucht","Grau-bläuliche Verfärbung der Haut bei Langzeitbehandlung","Verstopfung"],"gelegentlich":["Leitungsstörungen am Herzen (SA-Block, AV-Block)","Neu auftretende oder verstärkte Herzrhythmusstörungen, teils mit Herzstillstand","Periphere Nervenschädigung (Neuropathie) und Muskelschwäche (Myopathie)","Mundtrockenheit"],"sehrSelten":["Entzündung oder Schädigung des Sehnervs (Optikusneuropathie) mit Sehverlust","Chronische Lebererkrankung bis zur Zirrhose","Akutes Lungenversagen (ARDS), v. a. nach Operationen","Bronchospasmus","Syndrom der inadäquaten ADH-Sekretion (SIADH, Natriummangel)","Ausgeprägte Bradykardie oder Sinusarrest","Blutbildstörungen (hämolytische oder aplastische Anämie, Thrombozytopenie)","Vaskulitis, Haarausfall, Nebenhodenentzündung"],"unbekannt":["Torsade de pointes","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Angioödem, Anaphylaxie","Neutropenie, Agranulozytose","Pankreatitis","Verwirrtheit, Delir, Halluzinationen, Parkinsonismus"]},"schwangerschaft":"Kontraindiziert, ausser in lebensbedrohlichen Situationen: Amiodaron und sein Jod können die Schilddrüse des Ungeborenen schädigen (Unterfunktion, Kropf) und den Herzschlag verlangsamen.","stillzeit":"Kontraindiziert: Amiodaron geht in grossen Mengen in die Muttermilch über.","hinweise":["Konsequenter Sonnenschutz (hoher Lichtschutzfaktor, Kleidung) während der Behandlung und Monate danach – sonst Sonnenbrand und bläuliche Hautverfärbung.","Regelmässige Kontrollen: EKG, Schilddrüsen- und Leberwerte, Lungenfunktion und bei Sehstörungen augenärztliche Untersuchung.","Bei neuem Husten, Atemnot oder Sehverschlechterung sofort ärztlich melden.","Kein Grapefruitsaft; jedes neue Medikament ärztlich prüfen lassen – Wechselwirkungen bestehen noch Monate nach dem Absetzen."],"darreichung":["Tabletten","Injektionslösung"]},"amlodipin":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Muskulatur der Blutgefässe entspannt und die Arterien weitet. Amlodipin blockiert spannungsabhängige L-Typ-Calciumkanäle vor allem in der glatten Gefässmuskulatur; weniger Calcium strömt ein, der periphere Gefässwiderstand sinkt. Bei Angina pectoris vermindert es die Nachlast und damit den Sauerstoffbedarf des Herzens und erweitert die Herzkranzgefässe. Dank der sehr langen Halbwertszeit von 35–50 Stunden genügt eine Einnahme pro Tag; die volle Wirkung baut sich über einige Tage auf.","nebenwirkungen":{"sehrHaeufig":["Ödeme (Wassereinlagerungen, vor allem Knöchelschwellungen)"],"haeufig":["Kopfschmerzen (vor allem zu Beginn), Schwindel, Schläfrigkeit","Flush (Gesichtsrötung mit Wärmegefühl)","Herzklopfen (Palpitationen)","Bauchschmerzen, Übelkeit, Verdauungsstörungen, veränderte Stuhlgewohnheiten","Sehstörungen (auch Doppeltsehen)","Atemnot","Muskelkrämpfe","Müdigkeit, Schwäche"],"gelegentlich":["Hypotonie (tiefer Blutdruck), Synkope (Ohnmacht)","Herzrhythmusstörungen (inkl. Bradykardie, Vorhofflimmern)","Schlaflosigkeit, Stimmungsschwankungen, Depression","Zittern, Kribbeln, Geschmacksstörungen, Ohrensausen","Husten, Schnupfen, Mundtrockenheit, Erbrechen","Hautausschlag, Juckreiz, Nesselsucht, Haarausfall, vermehrtes Schwitzen","Gelenk-, Muskel- und Rückenschmerzen","Vermehrter Harndrang, Erektionsstörungen, Brustvergrösserung beim Mann"],"selten":["Verwirrtheit"],"sehrSelten":["Leukopenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Herzinfarkt","Zahnfleischwucherung (Gingivahyperplasie)","Hepatitis, Gelbsucht, erhöhte Leberwerte; Pankreatitis, Gastritis","Angioödem, Erythema multiforme, Stevens-Johnson-Syndrom, exfoliative Dermatitis","Hyperglykämie (erhöhter Blutzucker), periphere Neuropathie","Lichtempfindlichkeit, Vaskulitis (Gefässentzündung)"],"unbekannt":["Extrapyramidale Störungen (Bewegungsstörungen)","Toxische epidermale Nekrolyse"]},"schwangerschaft":"Sicherheit nicht belegt; nur anwenden, wenn keine sicherere Alternative besteht und die Erkrankung ein grösseres Risiko für Mutter und Kind darstellt.","stillzeit":"Amlodipin geht in geringer Menge in die Muttermilch über; über Stillen oder Behandlung wird ärztlich entschieden.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten; die volle Blutdrucksenkung tritt erst nach einigen Tagen ein.","Grapefruit und Grapefruitsaft meiden.","Knöchelschwellungen sind häufig; bei störenden Schwellungen ärztlich besprechen statt eigenmächtig absetzen.","Schwindel, Müdigkeit oder Kopfschmerzen können besonders zu Beginn die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Tabletten"]},"amorolfin":{"wirkmechanismus":"Hemmt das Wachstum von Pilzen und tötet sie ab, indem es den Aufbau ihrer Zellmembran stört. Amorolfin blockiert in der Ergosterol-Herstellung des Pilzes zwei Enzyme (Delta-14-Reduktase und Delta-7-Delta-8-Isomerase); es fehlt Ergosterol, und unbrauchbare Sterole reichern sich in der Membran an. Es wirkt gegen Dermatophyten, Hefen und viele Schimmelpilze. Aus dem eingetrockneten Lackfilm dringt der Wirkstoff in die Nagelplatte ein und bleibt dort mehrere Tage wirksam.","nebenwirkungen":{"selten":["Nagelveränderungen wie Verfärbung, brüchige oder abbrechende Nägel"],"sehrSelten":["Brennendes Gefühl der Haut rund um den Nagel"],"unbekannt":["Allergische Reaktionen, auch am ganzen Körper","Rötung, Juckreiz, Kontaktdermatitis, Nesselsucht oder Bläschen an der Auftragsstelle"]},"schwangerschaft":"Erfahrungen fehlen: nur anwenden, wenn klar notwendig (ärztliche Abwägung). Die Aufnahme in den Körper ist sehr gering.","stillzeit":"Erfahrungen fehlen: nur nach ärztlicher Abwägung; die Aufnahme in den Körper ist sehr gering.","hinweise":["Befallene Nagelanteile vor dem Auftragen abfeilen und den Nagel entfetten; die Nagelfeile nicht für gesunde Nägel verwenden.","Ohne Unterbruch weiterbehandeln, bis der Nagel gesund nachgewachsen ist (Fingernägel etwa 6 Monate, Zehennägel 9–12 Monate).","Keine künstlichen Nägel während der Behandlung; kosmetischer Nagellack frühestens 10 Minuten nach dem Auftragen und vor der nächsten Anwendung sorgfältig entfernen.","Bei Arbeit mit Lösungsmitteln (z. B. Verdünner) undurchlässige Handschuhe tragen, damit der Lackfilm nicht abgelöst wird."],"darreichung":["Nagellack (wirkstoffhaltig)"]},"amoxicillin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand stört. Amoxicillin hemmt die Penicillin-bindenden Proteine (Transpeptidasen), die den Zellwandbaustein Peptidoglykan quervernetzen; wachsende Bakterien gehen dadurch zugrunde (bakterizide Wirkung). Es wirkt gegen Streptokokken, Pneumokokken, Enterokokken und einen Teil der gramnegativen Keime wie Haemophilus influenzae und E. coli. Bakterien, die Beta-Laktamasen bilden (z. B. die meisten Staphylokokken), zerstören Amoxicillin – dafür gibt es die Kombination mit Clavulansäure.","nebenwirkungen":{"haeufig":["Durchfall","Übelkeit","Hautausschlag"],"gelegentlich":["Erbrechen","Nesselsucht (Urtikaria), Juckreiz"],"sehrSelten":["Pilzinfektionen von Haut und Schleimhäuten (Candidose)","Blutbildveränderungen (Leukopenie bis Agranulozytose, Thrombozytopenie, hämolytische Anämie)","Schwere allergische Reaktionen (Anaphylaxie, Angioödem, Serumkrankheit, allergische Gefässentzündung)","Krampfanfälle, Schwindel, Überaktivität","Antibiotika-assoziierte Kolitis (schwere Darmentzündung), schwarze Haarzunge","Leberentzündung, Gelbsucht durch Gallestau","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP, DRESS)","Interstitielle Nephritis (Nierenentzündung), Kristalle im Urin"],"unbekannt":["Jarisch-Herxheimer-Reaktion","Aseptische Meningitis (nicht bakterielle Hirnhautentzündung)","Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)","Arzneimittelinduziertes Enterokolitis-Syndrom (wiederholtes Erbrechen 1–4 Stunden nach Einnahme, vor allem bei Kindern)"]},"schwangerschaft":"Kann angewendet werden, wenn eine Antibiotikabehandlung nötig ist; langjährige Erfahrung ohne Hinweise auf eine Schädigung des Kindes.","stillzeit":"Erlaubt. Geht in kleinen Mengen in die Muttermilch über; beim Säugling sind Durchfall oder Pilzbefall möglich.","hinweise":["Kann unabhängig von den Mahlzeiten eingenommen werden; die verordnete Behandlungsdauer einhalten, auch wenn es schon besser geht.","Bei Hautausschlag, Atemnot oder Schwellungen sofort ärztlichen Rat einholen; eine bestätigte Allergie im Allergiepass vermerken.","Bei hoher Dosierung reichlich trinken.","Schwerer oder blutiger Durchfall, auch Wochen nach der Behandlung, muss ärztlich abgeklärt werden."],"darreichung":["Filmtabletten","Dispergierbare Tabletten","Pulver für Suspension zum Einnehmen (Sirup)"]},"amoxicillin-clavulansaeure":{"wirkmechanismus":"Tötet Bakterien ab und schützt das Antibiotikum vor bakteriellen Abwehrenzymen. Amoxicillin hemmt die Penicillin-bindenden Proteine und damit den Aufbau der bakteriellen Zellwand (bakterizide Wirkung). Clavulansäure hat selbst kaum antibakterielle Wirkung, blockiert aber irreversibel viele Beta-Laktamasen, mit denen Bakterien Amoxicillin sonst zerstören würden. Dadurch wirkt die Kombination zusätzlich gegen Beta-Laktamase-bildende Staphylokokken (nicht MRSA), Haemophilus influenzae, Moraxella catarrhalis, viele E.-coli-Stämme und Anaerobier.","nebenwirkungen":{"sehrHaeufig":["Durchfall (bei Erwachsenen)"],"haeufig":["Übelkeit (vor allem bei hohen Dosen)","Erbrechen","Pilzinfektionen von Haut und Schleimhäuten (z. B. Mund- oder Scheidenpilz)"],"gelegentlich":["Schwindel, Kopfschmerzen","Verdauungsbeschwerden","Anstieg der Leberwerte (AST/ALT)","Hautausschlag, Juckreiz, Nesselsucht"],"selten":["Vorübergehende Leukopenie, Neutropenie oder Thrombozytopenie","Erythema multiforme (Hautausschlag mit kokardenförmigen Flecken)"],"unbekannt":["Leberentzündung und Gelbsucht durch Gallestau (kann schwer sein, auch noch Wochen nach Behandlungsende)","Anaphylaxie, Angioödem, serumkrankheitsähnliche Reaktion, allergische Gefässentzündung","Agranulozytose, hämolytische Anämie, verlängerte Blutungs- und Gerinnungszeit","Krampfanfälle, Überaktivität, aseptische Meningitis","Antibiotika-assoziierte Kolitis (schwere Darmentzündung), schwarze Haarzunge","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP, DRESS)","Interstitielle Nephritis (Nierenentzündung), Kristalle im Urin","Arzneimittelinduziertes Enterokolitis-Syndrom, Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich. Bei vorzeitigem Blasensprung vor dem Geburtstermin nicht anwenden: Hinweise auf ein erhöhtes Risiko einer schweren Darmentzündung (nekrotisierende Enterokolitis) beim Neugeborenen.","stillzeit":"Erlaubt; beide Wirkstoffe gehen in geringen Mengen in die Muttermilch über (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Zu Beginn einer Mahlzeit einnehmen – so wird es besser vertragen und die Clavulansäure besser aufgenommen.","Die Behandlung soll ohne ärztliche Überprüfung nicht länger als 14 Tage dauern.","Gelbe Haut oder Augen, dunkler Urin oder heller Stuhl – auch Wochen nach Behandlungsende – sofort ärztlich abklären lassen.","Präparate verschiedener Stärken sind nicht beliebig austauschbar, weil sie unterschiedlich viel Clavulansäure enthalten."],"darreichung":["Filmtabletten","Dispergierbare Tabletten","Pulver für Suspension zum Einnehmen (Sirup)","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"amphotericin-b":{"wirkmechanismus":"Tötet Pilze ab, indem es Löcher in ihre Zellmembran reisst. Amphotericin B bindet an Ergosterol der Pilzmembran und bildet Poren, durch die Ionen und Zellbestandteile austreten; es wirkt so gegen ein breites Spektrum von Hefen und Schimmelpilzen sowie gegen Leishmanien. Eine schwächere Bindung an das Cholesterin menschlicher Zellen erklärt Nierenschäden und Infusionsreaktionen; die Verpackung in Liposomen (AmBisome) vermindert diese Giftigkeit deutlich. Zum Einnehmen wird Amphotericin B praktisch nicht aufgenommen und wirkt nur örtlich in Mund und Darm.","nebenwirkungen":{"sehrHaeufig":["Hypokaliämie (Kaliummangel)","Übelkeit, Erbrechen","Fieber, Schüttelfrost (Infusionsreaktion)"],"haeufig":["Hyponatriämie, Hypokalzämie, Hypomagnesiämie (Salzmangel im Blut), erhöhter Blutzucker","Kopfschmerzen","Herzrasen, Blutdruckabfall, Hitzegefühl (Flush)","Atemnot","Durchfall, Bauchschmerzen","Erhöhte Leber- und Nierenwerte (Kreatinin, Harnstoff)","Hautausschlag","Rücken- und Brustschmerzen"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Anaphylaktoide Reaktionen","Krampfanfälle","Bronchospasmus (Verkrampfung der Atemwege)"],"unbekannt":["Anaphylaxie, Angioödem","Herzrhythmusstörungen bis Herzstillstand","Akutes Nierenversagen","Rhabdomyolyse (Muskelzerfall)","Anämie (Blutarmut)","Bei Einnahme (Suspension, Lutschtabletten): Übelkeit, Durchfall, Reizung der Mundschleimhaut, allergische Hautreaktionen"]},"schwangerschaft":"Die Infusion nur bei zwingender Notwendigkeit, wenn der Nutzen das mögliche Risiko überwiegt. Präparate zum Einnehmen werden kaum aufgenommen; Anwendung nach ärztlicher Abwägung.","stillzeit":"Ob Amphotericin B nach Infusion in die Muttermilch übergeht, ist nicht bekannt; über Abstillen oder Therapieverzicht ärztlich entscheiden.","hinweise":["Liposomales (AmBisome) und herkömmliches Amphotericin B sind nicht austauschbar – die Dosierungen unterscheiden sich stark; Verwechslungen können tödlich sein.","Während der Infusionstherapie Nierenwerte, Kalium, Magnesium und Blutbild regelmässig kontrollieren.","Suspension oder Lutschtabletten nach dem Essen anwenden und möglichst lange im Mund lassen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung (liposomal)","Suspension zum Einnehmen","Lutschtabletten"]},"apixaban":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es einen zentralen Gerinnungsfaktor direkt blockiert. Apixaban bindet direkt, selektiv und reversibel an den Gerinnungsfaktor Xa, frei im Blut und im Gerinnsel, ohne Antithrombin zu benötigen. Dadurch wird weniger Thrombin gebildet und neue Gerinnsel entstehen nicht. Apixaban wird über mehrere Wege ausgeschieden (u. a. Abbau über CYP3A4, Transport durch P-Glykoprotein, nur etwa ein Viertel über die Nieren); als Gegenmittel steht Andexanet alfa zur Verfügung.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Blutungen und Blutergüsse (Hämatome)","Nasenbluten","Magen-Darm-Blutungen","Übelkeit","Blut im Urin","Erhöhte GGT (Leberwert)"],"gelegentlich":["Hirnblutung","Thrombozytopenie (verminderte Blutplättchen)","Überempfindlichkeit, allergisches Ödem, Anaphylaxie, Juckreiz","Blutungen aus Enddarm, Hämorrhoiden und Mund; Bluthusten; Blutungen im Bauchraum","Ungewöhnliche Scheidenblutungen","Erhöhte Leberwerte und erhöhtes Bilirubin","Hautausschlag, Haarausfall"],"selten":["Blutungen der Atemwege und im hinteren Bauchraum (retroperitoneal)","Muskelblutungen"],"unbekannt":["Erythema multiforme (Hautreaktion), Entzündung kleiner Hautgefässe (kutane Vaskulitis)","Antikoagulanzien-assoziierte Nephropathie (Nierenschädigung durch Blutungen in der Niere)"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber während der Schwangerschaft nicht anwenden.","stillzeit":"Unbekannt, ob Apixaban in die Muttermilch übergeht; entweder abstillen oder auf Apixaban verzichten.","hinweise":["Regelmässig zweimal täglich im Abstand von etwa 12 Stunden einnehmen, mit oder ohne Essen; Tabletten dürfen zerstossen werden.","Nicht eigenmächtig absetzen – Gefahr von Schlaganfall oder Thrombose.","Vor Operationen, Zahnbehandlungen und neuen Medikamenten Arzt oder Apotheke informieren; Nierenfunktion regelmässig kontrollieren.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, starke Kopfschmerzen, ungewöhnliche Blutergüsse) sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"aprepitant":{"wirkmechanismus":"Unterdrückt vor allem den verzögerten Brechreiz, der in den Tagen nach einer Chemotherapie auftritt. Aprepitant blockiert im Gehirn selektiv die Neurokinin-1-(NK1-)Rezeptoren, an denen der Botenstoff Substanz P Erbrechen auslöst. Es ergänzt damit die Wirkung von 5-HT3-Antagonisten (Setronen) und Dexamethason. Aprepitant wird über CYP3A4 abgebaut, hemmt dieses Enzym während der 3-tägigen Behandlung mässig und induziert danach CYP3A4 und CYP2C9 für einige Wochen.","nebenwirkungen":{"haeufig":["Schluckauf","Müdigkeit (Fatigue)","Appetitlosigkeit","Obstipation (Verstopfung)","Dyspepsie (Verdauungsbeschwerden)","Kopfschmerzen","Erhöhte Leberwerte (ALT)"],"gelegentlich":["Schwindel, Schläfrigkeit, Angst","Bauchschmerzen, Aufstossen, Mundtrockenheit, Blähungen, Übelkeit","Herzklopfen, Hitzewallungen","Hautausschlag, Akne","Schmerzen beim Wasserlassen","Febrile Neutropenie, Anämie (Blutarmut)"],"selten":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Langsamer Puls (Bradykardie)"],"unbekannt":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Angioödem, Nesselsucht, Juckreiz"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn es klar notwendig ist. Hormonelle Verhütung kann während und bis 2 Monate nach der Einnahme unzuverlässig sein.","stillzeit":"Nicht bekannt, ob Aprepitant in die Muttermilch übergeht; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Üblicherweise 3 Tage: 1 Stunde vor der Chemotherapie am Tag 1, dann je morgens an Tag 2 und 3; mit oder ohne Essen.","Bis 2 Monate nach der letzten Dosis zusätzlich nicht hormonell verhüten (z. B. Kondom).","Wer Phenprocoumon oder einen anderen Vitamin-K-Antagonisten nimmt: INR in den Wochen danach kontrollieren lassen.","Alle anderen Medikamente angeben – Aprepitant verändert die Spiegel vieler Arzneimittel."],"darreichung":["Kapseln"]},"ascorbinsaeure-vitamin-c":{"wirkmechanismus":"Ersetzt Vitamin C, das der Mensch nicht selbst bilden kann. Ascorbinsäure ist ein wasserlösliches Antioxidans und Cofaktor von Enzymen, die unter anderem Kollagen für Bindegewebe, Gefässe, Haut und Wundheilung sowie Carnitin und Noradrenalin bilden. Zudem verbessert es die Aufnahme von Eisen aus pflanzlicher Nahrung. Ein schwerer Mangel führt zu Skorbut mit Zahnfleischbluten, Blutergüssen und Wundheilungsstörungen; Überschüsse werden rasch über die Niere ausgeschieden.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden wie Durchfall, Übelkeit, Bauchkrämpfe (vor allem bei Dosen über 1 g pro Tag)","Oxalat-Nierensteine bei hohen Dosen","Hämolyse (Blutzerfall) bei G6PD-Mangel","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz)"]},"schwangerschaft":"In üblichen Dosen erlaubt; sehr hohe Dosen meiden.","stillzeit":"In üblichen Dosen erlaubt; Vitamin C geht in die Muttermilch über.","hinweise":["Kann Laborwerte verfälschen (z. B. Blutzuckermessung mit bestimmten Geräten, Tests auf Blut oder Zucker im Urin und Stuhl) – vor Untersuchungen angeben.","Brausetabletten in einem Glas Wasser auflösen; hohe Dosen auf mehrere Einnahmen verteilen.","Bei Einnahme hoher Dosen reichlich trinken (Vorbeugung von Nierensteinen)."],"darreichung":["Brausetabletten","Kautabletten"]},"atorvastatin":{"wirkmechanismus":"Senkt das Cholesterin, indem es dessen Herstellung in der Leber bremst. Atorvastatin hemmt selektiv und kompetitiv die HMG-CoA-Reduktase, das Schlüsselenzym der Cholesterinsynthese. Die Leberzellen bilden mehr LDL-Rezeptoren und holen vermehrt LDL-Cholesterin aus dem Blut; zusätzlich sinken die Triglyceride. Atorvastatin wird über CYP3A4 zu ebenfalls wirksamen Metaboliten abgebaut und über den Transporter OATP1B1 in die Leber aufgenommen – Hemmer dieser Wege erhöhen die Spiegel und das Risiko für Muskelschäden.","nebenwirkungen":{"haeufig":["Nasopharyngitis (Nasen-Rachen-Entzündung), Halsschmerzen, Nasenbluten","Allergische Reaktionen","Hyperglykämie (erhöhter Blutzucker)","Kopfschmerzen","Verstopfung, Blähungen, Verdauungsbeschwerden, Übelkeit, Durchfall","Muskel- und Gelenkschmerzen, Gliederschmerzen, Muskelkrämpfe, Gelenkschwellung, Rückenschmerzen","Abweichende Leberwerte, erhöhte CK (Muskelenzym)"],"gelegentlich":["Hypoglykämie (Unterzuckerung), Gewichtszunahme, Appetitlosigkeit","Albträume, Schlaflosigkeit","Schwindel, Kribbeln, Taubheitsgefühl, Geschmacksstörung, Gedächtnisverlust","Verschwommenes Sehen, Tinnitus (Ohrgeräusche)","Erbrechen, Bauchschmerzen, Aufstossen, Pankreatitis (Bauchspeicheldrüsenentzündung)","Hepatitis (Leberentzündung)","Nesselsucht, Ausschlag, Juckreiz, Haarausfall","Nackenschmerzen, Muskelermüdung, Unwohlsein, Schwäche, Brustschmerzen, Ödeme, Müdigkeit, Fieber"],"selten":["Myopathie, Myositis, Rhabdomyolyse (Muskelzerfall), Muskelriss","Tendinopathie (Sehnenschäden), teils mit Sehnenriss","Thrombozytopenie (Mangel an Blutplättchen)","Periphere Neuropathie, Sehstörungen","Cholestase (Gallestau)","Angioödem; blasenbildende Hautreaktionen bis zu Stevens-Johnson-Syndrom und toxischer epidermaler Nekrolyse"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Leberversagen","Hörverlust","Gynäkomastie (Brustvergrösserung beim Mann)"],"unbekannt":["Immunvermittelte nekrotisierende Myopathie (anhaltende Muskelschwäche)","Myasthenia gravis (Muskelschwäche), auch am Auge, oder deren Verschlechterung","Depression, sexuelle Funktionsstörungen, interstitielle Lungenerkrankung (Klasseneffekte der Statine)","Diabetes mellitus bei Personen mit Risikofaktoren"]},"schwangerschaft":"Kontraindiziert – Cholesterin ist für die Entwicklung des Ungeborenen nötig. Frauen im gebärfähigen Alter müssen zuverlässig verhüten; bei Eintritt einer Schwangerschaft sofort absetzen.","stillzeit":"Kontraindiziert – Übergang in die Muttermilch beim Menschen nicht bekannt, schwere Nebenwirkungen beim Säugling möglich.","hinweise":["Einmal täglich zu einer beliebigen, aber gleichbleibenden Tageszeit, mit oder ohne Essen.","Unerklärliche Muskelschmerzen, -schwäche oder -krämpfe, besonders mit Fieber oder dunklem Urin, sofort ärztlich melden.","Grosse Mengen Grapefruitsaft meiden; neue Medikamente (Antibiotika, Pilzmittel, HIV- oder Hepatitis-C-Mittel) auf Wechselwirkungen prüfen lassen.","Leberwerte vor Behandlungsbeginn und bei Bedarf kontrollieren; Ernährung und Bewegung bleiben wichtig."],"darreichung":["Filmtabletten"]},"atropin":{"wirkmechanismus":"Blockiert den Botenstoff Acetylcholin an den Organen, die vom «Ruhenerv» (Parasympathikus) gesteuert werden: Das Herz schlägt schneller, Speichel-, Schweiss- und Bronchialsekretion nehmen ab, Darm und Blase erschlaffen, die Pupille wird weit. Atropin ist ein kompetitiver Antagonist an allen Muskarinrezeptor-Subtypen (M1–M5). Als tertiäres Amin gelangt es ins Gehirn und kann in höheren Dosen Unruhe, Verwirrtheit und Halluzinationen auslösen. Bei Vergiftungen mit Cholinesterasehemmern hebt es die Überstimulation der Muskarinrezeptoren auf (nicht aber die Muskelschwäche an den Nikotinrezeptoren).","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit, verminderte Speichelbildung","Sehstörungen durch Pupillenerweiterung und Akkommodationslähmung, Lichtempfindlichkeit","Vermindertes Schwitzen mit Hautrötung und Wärmestau"],"haeufig":["Tachykardie (Herzrasen)","Schluckbeschwerden","Verstopfung, Reflux"],"gelegentlich":["Harnverhalt, Schwierigkeiten beim Wasserlassen","Allergische Reaktionen, Hautausschlag"],"selten":["Unruhe, Erregung, Verwirrtheit, Halluzinationen (vor allem bei hohen Dosen und älteren Menschen)","Krampfanfälle","Glaukomanfall (akuter Anstieg des Augeninnendrucks)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Kurzzeitige paradoxe Verlangsamung des Pulses bei sehr niedrigen Dosen","Herzrhythmusstörungen, Kammerflimmern","Augentropfen: Bindehautreizung, Lidschwellung, Kontaktallergie"]},"schwangerschaft":"Atropin geht auf das Ungeborene über und kann dessen Herzschlag beschleunigen. Nur bei klarer Notwendigkeit, z. B. im Notfall oder bei Narkosen, anwenden.","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung hemmen. Einmalige Gaben (z. B. bei Narkose) sind meist unproblematisch; bei wiederholter Anwendung ärztlich abwägen.","hinweise":["Nach Atropin-Augentropfen bleiben Sehen und Blendempfindlichkeit oft 7–14 Tage beeinträchtigt: in dieser Zeit nicht Auto fahren, Sonnenbrille tragen.","Bei Augentropfen den inneren Augenwinkel 1–2 Minuten zudrücken, damit weniger Wirkstoff in den Körper gelangt – besonders wichtig bei Kindern.","Bei lebensbedrohlichen Zuständen (Vergiftung, Herzstillstand) gelten die Gegenanzeigen nicht absolut – der Nutzen geht vor.","Augenschmerzen mit Sehverschlechterung und rotem Auge sofort ärztlich abklären (Glaukomanfall)."],"darreichung":["Injektionslösung","Augentropfen"]},"azelainsaeure":{"wirkmechanismus":"Wirkt gegen Aknebakterien, Entzündung und Verhornungsstörungen in den Talgdrüsenfollikeln. Azelainsäure ist eine natürlich vorkommende Dicarbonsäure, die das Wachstum von Cutibacterium acnes und Staphylococcus epidermidis hemmt (u. a. über eine Hemmung der bakteriellen Eiweisssynthese) und die übermässige Verhornung der Follikelwand normalisiert. Zusätzlich vermindert sie entzündungsfördernde Sauerstoffradikale, was bei der Rosazea im Vordergrund steht. Nur ein kleiner Teil wird über die Haut aufgenommen.","nebenwirkungen":{"sehrHaeufig":["Brennen, Juckreiz, Schmerzen und Rötung an der Auftragsstelle"],"haeufig":["Schuppung und Trockenheit der Haut","Kribbeln (Parästhesie), Hautausschlag","Hautreizung, Verfärbung der Haut"],"gelegentlich":["Hautentzündung (Dermatitis), Schwellung (Ödem)","Akne, vermehrte Talgbildung (Seborrhö)","Hellere Hautflecken (Depigmentierung)"],"selten":["Lippenentzündung (Cheilitis)","Überempfindlichkeitsreaktionen mit Angioödem, Gesichts- oder Augenschwellung, Atemnot"],"unbekannt":["Verschlechterung eines Asthmas"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich; es gelangt nur wenig Wirkstoff in den Körper.","stillzeit":"Nach Abwägung möglich; nicht auf die Brust auftragen, der Säugling darf nicht mit behandelter Haut in Kontakt kommen.","hinweise":["Zweimal täglich dünn auf die gereinigte Haut auftragen und einmassieren; danach Hände waschen.","Brennen und Juckreiz zu Beginn sind häufig und klingen meist nach einigen Tagen ab.","Die Wirkung zeigt sich meist nach etwa 4 Wochen; regelmässig anwenden.","Keine luftdichten Verbände; bei Rosazea alkoholhaltige Reinigungsmittel und reizende Kosmetika meiden."],"darreichung":["Creme (20 %)","Gel (15 %)"]},"azithromycin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung stoppt. Azithromycin bindet an die 50S-Untereinheit der bakteriellen Ribosomen und blockiert die Verlängerung der Eiweisskette. Es reichert sich stark im Gewebe und in Abwehrzellen an und wird sehr langsam ausgeschieden (Halbwertszeit rund 2–3 Tage), daher die kurze Behandlungsdauer. Anders als Clarithromycin und Erythromycin hemmt es CYP3A4 kaum.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Bei Augentropfen: Brennen, Stechen oder Reizung am Auge"],"haeufig":["Übelkeit, Erbrechen, Bauchschmerzen","Kopfschmerzen","Veränderte Laborwerte (weniger Lymphozyten, mehr Eosinophile, tieferes Bikarbonat)"],"gelegentlich":["Pilzinfektionen (Candidose), Scheideninfektion","Schwindel, Schläfrigkeit, Geschmacksstörungen, Kribbeln","Hörstörungen, Drehschwindel","Herzklopfen","Hepatitis (Leberentzündung), erhöhte Leberwerte","Hautausschlag, Juckreiz, Nesselsucht","Angioödem, Überempfindlichkeitsreaktionen","Leukopenie, Neutropenie (weniger weisse Blutkörperchen)"],"selten":["Unruhe (Agitiertheit)","Cholestatische Gelbsucht","Lichtempfindlichkeit der Haut","DRESS und akute generalisierte exanthematische Pustulose (schwere Hautreaktionen)"],"unbekannt":["QT-Verlängerung, Torsade de pointes und andere Herzrhythmusstörungen","Leberversagen, fulminante Hepatitis","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Anaphylaxie (schwere allergische Reaktion)","Hörverlust bis Taubheit, Tinnitus","Pseudomembranöse Kolitis, Pankreatitis","Thrombozytopenie, hämolytische Anämie","Krampfanfälle, Verschlechterung einer Myasthenia gravis, akutes Nierenversagen"]},"schwangerschaft":"Grosse Beobachtungsstudien zeigen kein erhöhtes Fehlbildungsrisiko, die Daten sind aber nicht abschliessend. Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; Augentropfen sind vertretbar.","stillzeit":"Geht in die Muttermilch über; beim Säugling sind Durchfall und Pilzbefall möglich. Nach ärztlicher Abwägung anwendbar, Kind beobachten.","hinweise":["Die Wirkung hält nach der letzten Dosis noch mehrere Tage an – die Packung trotzdem wie verordnet vollständig einnehmen.","Antazida (Magensäurebinder) nicht gleichzeitig einnehmen.","Bei Herzklopfen, Ohnmacht, Gelbsucht oder schwerem Hautausschlag sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten","Pulver für Suspension zum Einnehmen","Pulver zur Herstellung einer Infusionslösung","Augentropfen (Einzeldosen)"]}});
